"""Lognormal shell extension via GLASS.

N-body lightcones typically stop at moderate redshift (CosmoGrid caps near
``z ~ 3.5``), but the CMB-lensing kernel and the high-z tails of weak-lensing /
clustering n(z) reach far beyond that. This module fills the gap with
*cross-correlated* lognormal matter shells generated by GLASS from CCL matter
angular power spectra, so the shells carry the correct cross-shell two-point
statistics the integrated CMB-lensing kernel needs.

Requires the optional ``glass`` dependency (``pip install forwardmodel[lognormal]``).
"""

from __future__ import annotations

import numpy as np
import healpy as hp
import pyccl as ccl

from .shells import ShellStack


def _matter_cls_glass_order(cosmo, windows, lmax):
    """Pairwise matter C_ell for GLASS tophat windows, in GLASS field order.

    For field ``i`` GLASS wants the spectra ordered ``j = i, i-1, ..., 0``.
    Each window's ``(za, wa)`` is fed to a CCL ``NumberCountsTracer`` with
    bias 1, giving the standard Limber matter-density projection per shell.
    """
    ells = np.arange(lmax + 1, dtype=np.float64)
    tracers = []
    for w in windows:
        za = np.asarray(w.za, dtype=float)
        wa = np.asarray(w.wa, dtype=float)
        tracers.append(ccl.NumberCountsTracer(
            cosmo.ccl, has_rsd=False,
            dndz=(za, wa), bias=(za, np.ones_like(za)),
        ))

    spectra = []
    n = len(windows)
    for i in range(n):
        for j in range(i, -1, -1):
            cl = ccl.angular_cl(cosmo.ccl, tracers[i], tracers[j], ells)
            spectra.append(np.asarray(cl, dtype=np.float64))
    return spectra


def lognormal_shells(cosmo, z_edges, nside, rng=None, lmax=None, shift=None):
    """Generate cross-correlated lognormal overdensity shells.

    Parameters
    ----------
    cosmo : forwardmodel.Cosmology
    z_edges : array_like
        Redshift bin edges; ``len(z_edges) - 1`` shells are produced.
    nside : int
        HEALPix resolution.
    rng : np.random.Generator, optional
    lmax : int, optional
        Defaults to ``3 * nside - 1``.
    shift : callable, optional
        Lognormal shift as a function of redshift, ``shift(z) -> float``.
        Defaults to GLASS's standard shift of 1, which reproduces
        ``delta = e^{G - sigma^2/2} - 1``.

    Returns
    -------
    ShellStack
        Overdensity shells covering ``z_edges``.
    """
    import glass

    if rng is None:
        rng = np.random.default_rng()
    if lmax is None:
        lmax = 3 * nside - 1

    z_edges = np.asarray(z_edges, dtype=float)
    n_shells = len(z_edges) - 1
    npix = hp.nside2npix(nside)

    # GLASS samples each tophat window at spacing ``win_dz``. Too coarse a step
    # leaves thin shells with too few points for CCL's density-kernel spline
    # (it needs ~8), so scale the step to the thinnest shell rather than the
    # fixed 0.01 default — N-body lightcone shells can be ~0.01 wide at low z.
    win_dz = min(0.01, float(np.min(np.diff(z_edges))) / 8.0)
    windows = glass.tophat_windows(z_edges, dz=win_dz)
    if len(windows) != n_shells:
        raise RuntimeError("GLASS produced an unexpected number of windows")

    spectra = _matter_cls_glass_order(cosmo, windows, lmax)
    fields = (glass.lognormal_fields(windows) if shift is None
              else glass.lognormal_fields(windows, shift=shift))

    # Gaussian-side C_ell that reproduce the target matter C_ell after the
    # lognormal transform. The inversion can leave tiny negative auto-C_ell at
    # high ell from numerical noise; "clip" tolerates those (unlike "nearest").
    gls = glass.compute_gaussian_spectra(fields, spectra)
    gls = glass.regularized_spectra(gls, method="clip")

    delta = np.empty((n_shells, npix), dtype=np.float64)
    for i, field in enumerate(glass.generate(fields, gls, nside, rng=rng)):
        delta[i] = np.asarray(field)

    return ShellStack.from_overdensity(delta, z_edges[:-1], z_edges[1:],
                                       nside=nside)
